# Bio Lab 1 Automation Script (V1.2 - Outage & Reload Hardened)
# Automates the Analyze and Extract steps of the biology pipeline.
# Resilient against power outages, interrupted extractions, latched input ports, and game reloads.

collector = get_component("bio_collector_1")
shop = get_component("shop")
inv = get_component("inventory")

# Connect ports to home Base Inventory
self.input.connect("inventory")
self.output.connect("inventory")

while True:
    # 1. Drain output slot if sample or returned/unloaded reagents are present
    if self.output.count() > 0:
        for stack in self.output.stacks():
            res_send = self.output.send(stack.id, stack.count)
            if res_send.status == "ok":
                print(f"Sent {res_send.moved}x {stack.id} to inventory.")
            elif res_send.status == "busy":
                sleep(0.5)
                break
            else:
                print("Output send status:", res_send.status, "-", res_send.message)
                sleep(1.0)
                break

    # 2. Check specimen chamber
    specimen = self.specimen

    if specimen is None:
        # If input has stray reagents while chamber is empty, eject them to clear the port
        if self.input.count() > 0:
            for stack in self.input.stacks():
                try:
                    ej_res = self.input.eject("inventory", stack.id, stack.count)
                    if ej_res.status == "ok":
                        print(f"Ejected stray {stack.count}x {stack.id} from lab input to inventory.")
                except Exception:
                    pass

        # Chamber is empty - pull available specimen from Collector
        if collector and collector.cargo is not None:
            t_res = self.take_from(collector)
            if t_res.status == "ok":
                print("Transferred specimen from collector to lab chamber.")
            elif t_res.status not in ["source_empty", "busy", "source_busy"]:
                print("take_from status:", t_res.status, "-", t_res.message)
        sleep(0.5)
        continue

    # 3. Analyze if newly collected
    if specimen.stage == "collected":
        print("Analyzing specimen...")
        a_res = self.analyze()
        if a_res.status == "ok":
            print(f"Analysis complete: {a_res.info.name} ({a_res.info.fragment_id}). Recipe: {a_res.info.required_recipe}")
        elif a_res.status != "busy":
            print("analyze error:", a_res.status, "-", a_res.message)
        sleep(0.5)
        continue

    # 4. Extract if analyzed
    if specimen.stage == "analyzed":
        recipe = specimen.recipe or {}  # dict of {reagent_id: count}
        loaded = self.loaded_reagents or {}

        # Safety check: if loaded reagents contain anything not in recipe, unload them
        mismatched_loaded = False
        for r_id, r_qty in loaded.items():
            if r_id not in recipe or r_qty > recipe.get(r_id, 0):
                mismatched_loaded = True
                break

        if mismatched_loaded:
            print("Detected mismatched loaded reagents after reload/outage. Unloading to output...")
            unl_res = self.unload_reagents()
            if unl_res.status == "ok":
                sleep(0.5)
                continue

        # Check for unneeded reagents sitting in self.input
        if self.input.count() > 0:
            for stack in self.input.stacks():
                needed_qty = recipe.get(stack.id, 0) - loaded.get(stack.id, 0)
                if needed_qty > 0:
                    # Valid reagent needed for current recipe - load it!
                    load_qty = min(stack.count, needed_qty)
                    load_res = self.load(stack.id, load_qty)
                    print(f"Loaded {load_qty}x {stack.id} from input buffer. Status: {load_res.status}")
                else:
                    # Stale / wrong reagent latched in input buffer - eject to inventory
                    try:
                        ej_res = self.input.eject("inventory", stack.id, stack.count)
                        if ej_res.status == "ok":
                            print(f"Ejected unwanted {stack.count}x {stack.id} from lab input to inventory.")
                    except Exception:
                        pass
            sleep(0.5)
            continue

        # Check which reagents are still missing
        needs_loading = False
        for reagent_id, req_qty in recipe.items():
            curr_qty = loaded.get(reagent_id, 0)
            missing = req_qty - curr_qty
            if missing > 0:
                needs_loading = True
                # Ensure inventory has enough stock; if not, buy from shop
                inv_stock = inv.count(reagent_id) if inv else 0
                if inv_stock < missing:
                    buy_qty = missing - inv_stock
                    buy_res = shop.buy(reagent_id, buy_qty)
                    if buy_res.status == "ok":
                        print(f"Auto-purchased {buy_qty}x {reagent_id} from shop.")
                    else:
                        print(f"Failed to buy {reagent_id}:", buy_res.status, "-", buy_res.message)
                        sleep(2.0)
                        break

                # Pull reagent into input buffer
                take_res = self.input.take(reagent_id, missing)
                if take_res.status in ["ok", "partial"] and take_res.moved > 0:
                    load_res = self.load(reagent_id, take_res.moved)
                    print(f"Loaded {take_res.moved}x {reagent_id}. Status: {load_res.status}")
                elif take_res.status == "busy":
                    sleep(0.5)
                elif take_res.status == "target_wrong_material":
                    # Mismatched material will be ejected on next pass
                    sleep(0.5)
                else:
                    sleep(0.5)
                break

        if not needs_loading:
            # All reagents loaded, perform extraction!
            print(f"Extracting sample for {specimen.fragment_id}...")
            ext_res = self.extract()
            if ext_res.status == "ok":
                print(f"Successfully extracted sample: {specimen.fragment_id}")
            elif ext_res.status != "busy":
                print("extract error:", ext_res.status, "-", ext_res.message)
            sleep(0.5)
            continue

    sleep(0.5)

# Bio Exchange 1 Automation Script (V1.2 - Outage & Reload Hardened)
# Automatically selects active Bio Orders and fulfills them with delivered samples.
# Robust against power outages, buffer latching, mismatched items, and game reloads.

inv = get_component("inventory")

# Ensure ports are connected to Base Inventory
self.input.connect("inventory")
self.output.connect("inventory")

while True:
    # 1. Drain surplus output slot if present (e.g. from shared order completions)
    if self.output.count() > 0:
        for stack in self.output.stacks():
            res_send = self.output.send(stack.id, stack.count)
            if res_send.status == "ok":
                print(f"Drained surplus {res_send.moved}x {stack.id} from exchange output to inventory.")
            elif res_send.status == "busy":
                sleep(0.5)
                break
            else:
                print("Exchange output drain status:", res_send.status, "-", res_send.message)
                sleep(1.0)
                break

    # 2. Check and maintain active order
    active = self.active_order()

    # If no active order, or current order is complete (100%), select the next available incomplete order
    if active is None or active.percent >= 1.0 or active.status == "complete":
        available_orders = self.orders()
        chosen_order_id = None
        for ord_info in available_orders:
            if ord_info.status != "complete" and getattr(ord_info, "percent", 0.0) < 1.0:
                # Check if there is still remaining unfulfilled demand
                is_needed = False
                for item_id, count_needed in ord_info.requires.items():
                    deliv = ord_info.delivered.get(item_id, 0)
                    in_tr = ord_info.in_transit.get(item_id, 0)
                    if deliv + in_tr < count_needed:
                        is_needed = True
                        break
                if is_needed:
                    chosen_order_id = ord_info.id
                    break

        if chosen_order_id and (active is None or chosen_order_id != active.id):
            set_res = self.set_order(chosen_order_id)
            if set_res.status == "ok":
                print(f"Assigned new Bio Order: {chosen_order_id}")
                active = self.active_order()
            else:
                print(f"Failed to set order {chosen_order_id}:", set_res.status, "-", set_res.message)
                sleep(2.0)
                continue
        elif not chosen_order_id:
            # All available orders completed
            sleep(5.0)
            continue

    if not active:
        sleep(2.0)
        continue

    # 3. Handle self.input buffer: inspect and clear/deliver any existing material FIRST
    if self.input.count() > 0:
        for stack in self.input.stacks():
            # Check if this stack qualifies for the current active order
            if self.matches_order(stack.id):
                # Qualifying item present in buffer — deliver it!
                deliv_res = self.deliver()
                if deliv_res.status in ["ok", "complete"]:
                    print(f"Delivered 1x {stack.id} for {active.id}! Status: {deliv_res.status}")
                elif deliv_res.status == "busy":
                    sleep(0.5)
                else:
                    print("Deliver status:", deliv_res.status, "-", deliv_res.message)
                    sleep(1.0)
                break
            else:
                # Mismatched or leftover item from previous order / reload!
                # Eject it back to inventory so the input buffer is cleared.
                try:
                    e_res = self.input.eject("inventory", stack.id, stack.count)
                    if e_res.status == "ok":
                        print(f"Ejected mismatched {stack.count}x {stack.id} from exchange input back to inventory.")
                    elif e_res.status == "busy":
                        sleep(0.5)
                    else:
                        print(f"Failed to eject {stack.id} from exchange input:", e_res.status, "-", e_res.message)
                        sleep(1.0)
                except Exception as ex:
                    print("Error ejecting mismatched input:", ex)
                    sleep(1.0)
                break
        sleep(0.5)
        continue

    # 4. Identify which fragment is still needed for the active order
    target_item = None
    for item_id, count_needed in active.requires.items():
        deliv = active.delivered.get(item_id, 0)
        in_tr = active.in_transit.get(item_id, 0)
        if deliv + in_tr < count_needed:
            target_item = item_id
            break

    if target_item is None:
        sleep(2.0)
        continue

    # 5. Pull needed sample from Base Inventory into self.input
    if inv and inv.count(target_item) > 0:
        take_res = self.input.take(target_item, 1)
        if take_res.status == "ok":
            print(f"Pulled {target_item} from inventory to exchange input.")
        elif take_res.status == "busy":
            sleep(0.5)
        elif take_res.status == "target_wrong_material":
            # If buffer still holds another item, the next loop pass will eject it
            sleep(0.5)
        else:
            print("Take from inventory status:", take_res.status, "-", take_res.message)
            sleep(1.0)
    else:
        # Sample not yet available in inventory; wait for Bio Lab
        sleep(2.0)

# Bio Exchange 1 Automation Script (V1.3 - Dynamic Declutter & Outage Hardened)
#
# Functions:
# 1. Scans Base Inventory for any bio samples that match ANY incomplete Bio Order.
# 2. Prioritizes orders that have ready stock in inventory, pulling and delivering them immediately to declutter.
# 3. Falls back to the primary incomplete order when no inventory stock is available.
# 4. Outage and reload safe: clears and ejects mismatched/stale input buffer items back to inventory.
# 5. Drains surplus returned samples from output buffer.

inv = get_component("inventory")

# Ensure ports are connected to Base Inventory
self.input.connect("inventory")
self.output.connect("inventory")

print("Bio Exchange 1 online.")

while True:
    # 1. Drain surplus output slot if present
    if self.output.count() > 0:
        for stack in self.output.stacks():
            res_send = self.output.send(stack.id, stack.count)
            if res_send.status == "ok":
                print(f"Drained surplus {res_send.moved}x {stack.id} from exchange output to inventory.")
            elif res_send.status == "busy":
                sleep(0.5)
                break
            else:
                sleep(1.0)
                break

    active = self.active_order()

    # 2. Handle self.input buffer: deliver matching item or eject mismatched/stale items
    if self.input.count() > 0:
        for stack in self.input.stacks():
            if active and self.matches_order(stack.id):
                deliv_res = self.deliver()
                if deliv_res.status in ["ok", "complete"]:
                    print(f"Delivered 1x {stack.id} for {active.id}! Status: {deliv_res.status}")
                elif deliv_res.status == "busy":
                    sleep(0.5)
                else:
                    sleep(1.0)
                break
            else:
                # Eject mismatched or leftover item back to inventory to free the input buffer
                try:
                    e_res = self.input.eject("inventory", stack.id, stack.count)
                    if e_res.status == "ok":
                        print(f"Ejected mismatched {stack.count}x {stack.id} from exchange input back to inventory.")
                    elif e_res.status == "busy":
                        sleep(0.5)
                    else:
                        sleep(1.0)
                except Exception:
                    sleep(1.0)
                break
        sleep(0.5)
        continue

    # 3. Inventory Declutter Scan: Find any incomplete order with items ready in Inventory
    ready_order_id = None
    ready_item_id = None

    # Check active order first if it has items ready in inventory
    if active and active.status != "complete" and getattr(active, "percent", 0.0) < 1.0:
        for item_id, count_needed in active.requires.items():
            deliv = active.delivered.get(item_id, 0)
            in_tr = active.in_transit.get(item_id, 0)
            if deliv + in_tr < count_needed and inv and inv.count(item_id) > 0:
                ready_order_id = active.id
                ready_item_id = item_id
                break

    # If active order doesn't have items in inventory, search all available incomplete orders
    all_orders = self.orders()
    if ready_order_id is None:
        for ord_info in all_orders:
            if ord_info.status != "complete" and getattr(ord_info, "percent", 0.0) < 1.0:
                for item_id, count_needed in ord_info.requires.items():
                    deliv = ord_info.delivered.get(item_id, 0)
                    in_tr = ord_info.in_transit.get(item_id, 0)
                    if deliv + in_tr < count_needed and inv and inv.count(item_id) > 0:
                        ready_order_id = ord_info.id
                        ready_item_id = item_id
                        break
                if ready_order_id:
                    break

    # 4. If an inventory-backed order is found, switch to it and deliver!
    if ready_order_id:
        if active is None or active.id != ready_order_id:
            set_res = self.set_order(ready_order_id)
            if set_res.status == "ok":
                print(f"[EXCHANGE] Switched to order '{ready_order_id}' to deliver available inventory items.")
                active = self.active_order()
            else:
                sleep(1.0)
                continue

        # Pull 1 unit of the matching item from Inventory
        take_res = self.input.take(ready_item_id, 1)
        if take_res.status == "ok":
            print(f"[EXCHANGE] Pulled 1x {ready_item_id} from inventory for {ready_order_id}.")
        elif take_res.status == "busy":
            sleep(0.5)
        else:
            sleep(0.5)
        continue

    # 5. Fallback: No items currently in inventory match any incomplete order
    # Ensure we have an incomplete active order assigned so Bio Collector knows what to hunt
    if active is None or active.percent >= 1.0 or active.status == "complete":
        chosen_order_id = None
        for ord_info in all_orders:
            if ord_info.status != "complete" and getattr(ord_info, "percent", 0.0) < 1.0:
                is_needed = False
                for item_id, count_needed in ord_info.requires.items():
                    deliv = ord_info.delivered.get(item_id, 0)
                    in_tr = ord_info.in_transit.get(item_id, 0)
                    if deliv + in_tr < count_needed:
                        is_needed = True
                        break
                if is_needed:
                    chosen_order_id = ord_info.id
                    break

        if chosen_order_id and (active is None or chosen_order_id != active.id):
            set_res = self.set_order(chosen_order_id)
            if set_res.status == "ok":
                print(f"[EXCHANGE] Assigned new active Bio Order: {chosen_order_id}")
                active = self.active_order()
            else:
                sleep(2.0)
                continue
        elif not chosen_order_id:
            # All available Bio Orders completed!
            sleep(5.0)
            continue

    # All available inventory samples delivered, waiting for new samples from field/lab
    sleep(2.0)

# Bio Exchange 1 Automation Script (V1.5 - Biome-Aware & Outage Hardened)
#
# Functions:
# 1. Inspects outpost biome (e.g. "frozen_plains" / "frozen").
# 2. Ensures active orders are strictly COMPLETABLE (local biome or 100% fulfilled by existing inventory).
# 3. Runs a periodic inventory sweep every SWEEP_DELAY seconds to deliver matching inventory items.
# 4. Never gets stuck on orders requiring specimens from foreign biomes.
# 5. Keeps clean buffers and drains surplus samples.

SWEEP_DELAY = 10.0  # Seconds between inventory sweeps

inv = get_component("inventory")
self.input.connect("inventory")
self.output.connect("inventory")

def get_my_biome():
    if hasattr(self, "outpost") and self.outpost:
        return getattr(self.outpost, "biome", None)
    return None

def is_local_order(ord_info, my_biome):
    if not my_biome:
        return True
    ord_biome = getattr(ord_info, "biome", None)
    if not ord_biome:
        return True
    return ord_biome == my_biome or ord_biome in my_biome or my_biome in ord_biome

def is_completable(ord_info, my_biome):
    # An order is completable if:
    # 1. It belongs to our local biome (so Bio Collector can find missing fragments here), OR
    # 2. Base Inventory already has 100% of all remaining required items right now.
    if is_local_order(ord_info, my_biome):
        return True

    # Foreign biome: only completable if inventory already holds all remaining required units
    if not inv:
        return False
    for item_id, count_needed in ord_info.requires.items():
        deliv = ord_info.delivered.get(item_id, 0)
        in_tr = ord_info.in_transit.get(item_id, 0)
        rem = count_needed - (deliv + in_tr)
        if rem > 0 and inv.count(item_id) < rem:
            return False
    return True

def drain_output():
    if self.output.count() > 0:
        for stack in self.output.stacks():
            self.output.send(stack.id, stack.count)

def clear_input():
    if self.input.count() > 0:
        for stack in self.input.stacks():
            try:
                self.input.eject("inventory", stack.id, stack.count)
            except Exception:
                pass

print("Bio Exchange 1 online.")

while True:
    my_biome = get_my_biome()
    drain_output()
    clear_input()

    # --- INVENTORY SWEEP ---
    # Deliver anything in inventory that any COMPLETABLE order needs
    all_orders = self.orders()
    delivered_count = 0

    for ord_info in all_orders:
        if ord_info.status == "complete" or getattr(ord_info, "percent", 0.0) >= 1.0:
            continue

        # Skip orders that cannot be completed from this base
        if not is_completable(ord_info, my_biome):
            continue

        for item_id, count_needed in ord_info.requires.items():
            deliv = ord_info.delivered.get(item_id, 0)
            in_tr = ord_info.in_transit.get(item_id, 0)
            remaining_needed = count_needed - (deliv + in_tr)

            if remaining_needed <= 0:
                continue

            available_in_inv = inv.count(item_id) if inv else 0
            if available_in_inv <= 0:
                continue

            to_deliver = min(remaining_needed, available_in_inv)

            # Switch order if needed
            active = self.active_order()
            if active is None or active.id != ord_info.id:
                set_res = self.set_order(ord_info.id)
                if set_res.status != "ok":
                    print(f"Failed to set order {ord_info.id}: {set_res.status}")
                    continue
                print(f"[SWEEP] Switched to completable order {ord_info.id} ({getattr(ord_info, 'biome', 'local')}) to deliver {to_deliver}x {item_id}")

            # Deliver available items
            for _ in range(to_deliver):
                drain_output()
                take_res = self.input.take(item_id, 1)
                if take_res.status != "ok":
                    if take_res.status == "target_wrong_material":
                        clear_input()
                    break

                deliv_res = self.deliver()
                while deliv_res.status == "busy":
                    sleep(0.2)
                    deliv_res = self.deliver()

                if deliv_res.status in ["ok", "complete"]:
                    delivered_count += 1
                    print(f"[SWEEP] Delivered 1x {item_id} -> {ord_info.id} (Status: {deliv_res.status})")
                else:
                    print(f"[SWEEP] Deliver error: {deliv_res.status} - {deliv_res.message}")
                    break

    drain_output()
    clear_input()

    if delivered_count > 0:
        print(f"[SWEEP] Sweep complete: delivered {delivered_count} sample(s).")

    # --- POST-SWEEP IDLE ORDER SELECTION ---
    # Ensure an active order is set that belongs to our local biome so Bio Collector has a valid target
    active = self.active_order()
    needs_new_order = (
        active is None
        or active.percent >= 1.0
        or active.status == "complete"
        or not is_local_order(active, my_biome)
    )

    if needs_new_order:
        for ord_info in all_orders:
