]

# State tracking
shedded_machines = set()
last_elevation = clock.get_elevation()
night_duration = 10.0  # Estimated night length in game hours (calibrates dynamically)
sunset_hour = None
last_advisory_day = -1
peak_day_battery_wh = 0.0

def get_battery_info(grid, power_ctrl):
    for bat_id in ["battery_1", "battery", "battery_2"]:
        try:
            b = get_component(bat_id)
            if b is not None and hasattr(b, "get_level"):
                return b.get_level(), b.get_capacity()
        except Exception:
            pass
    if grid is not None:
        stored = getattr(grid, "battery_stored", None) or getattr(grid, "stored", None)
        cap = getattr(grid, "battery_capacity", None) or getattr(grid, "capacity", None)
        if stored is not None and cap is not None:
            return stored, cap
    if power_ctrl is not None:
        try:
            tot = power_ctrl.total()
            stored = getattr(tot, "battery_stored", None) or getattr(tot, "stored", None)
            cap = getattr(tot, "battery_capacity", None) or getattr(tot, "capacity", None)
            if stored is not None and cap is not None:
                return stored, cap
        except Exception:
            pass
    return 0.0, 500.0

print("Solar 1 & Power Grid Controller online.")

while True:
    # 1. Closed-loop solar tracking
    elevation = clock.get_elevation()
    tilt = max(0, min(90, 90 - elevation))
    self.set_tilt(tilt)

    current_hour = clock.elapsed_game_hours()
    current_day = clock.get_day()

    # 2. Track day/night transitions & calibrate night duration
    if last_elevation > 0 and elevation == 0:
        # Sunset detected
        sunset_hour = current_hour
        print(f"[POWER] Sunset detected at day {current_day} (hour {current_hour:.1f}). Calibrated night mode active.")
    elif last_elevation == 0 and elevation > 0:
        # Sunrise detected
        if sunset_hour is not None:
            measured_night = current_hour - sunset_hour
            if 2.0 < measured_night < 20.0:
                night_duration = measured_night
                print(f"[POWER] Sunrise detected. Night lasted {night_duration:.1f} game hours.")
        peak_day_battery_wh = 0.0

    last_elevation = elevation

    # 3. Read grid & battery state
    grid = None
    if power:
        try:
            grid = power.grid(self.id)
            if grid is None:
                grids = power.grids()
                if grids:
                    grid = grids[0]
        except Exception:
            pass

    stored_wh, capacity_wh = get_battery_info(grid, power)
    peak_day_battery_wh = max(peak_day_battery_wh, stored_wh)

    consumed_w = getattr(grid, "consumed", 0.0) if grid else 0.0
    generated_w = getattr(grid, "generated", 0.0) if grid else 0.0
    is_night = (elevation == 0)

    # 4. Night endurance calculation & load shedding
    if is_night:
        if sunset_hour is not None:
            hours_into_night = max(0.0, current_hour - sunset_hour)
            remaining_night = max(0.5, night_duration - hours_into_night)
        else:
            remaining_night = night_duration / 2.0

        # Energy required to survive until sunrise with a 15% safety buffer
        wh_needed = consumed_w * remaining_night * 1.15
        battery_pct = (stored_wh / capacity_wh) if capacity_wh > 0 else 0.0

        # Trigger load shedding if battery cannot last the night OR if battery drops below 20%
        deficit_detected = (stored_wh < wh_needed)
        emergency_low = (battery_pct < 0.20)

        if deficit_detected or emergency_low:
            for m_id in NON_CRITICAL_MACHINES:
                try:
                    if power and power.can_power_off(m_id) and power.is_powered(m_id):
                        res = power.set_powered(m_id, False)
                        if res.status == "ok":
                            shedded_machines.add(m_id)
                            reason = "Emergency reserve guard (<20%)" if emergency_low else f"Insufficient storage ({stored_wh:.0f} Wh < {wh_needed:.0f} Wh needed)"
                            print(f"[POWER GUARD] Shed load: disabled {m_id}. Reason: {reason}.")
                except Exception:
                    pass

    # 5. Daytime recovery (hysteresis: restore shedded machines when solar surplus exists)
    else:
        # Solar is active; check if we have surplus generation to safely bring loads back
        if shedded_machines and generated_w > (consumed_w + 10.0) and stored_wh > 30.0:
            for m_id in list(shedded_machines):
                try:
                    if power and power.can_power_off(m_id) and not power.is_powered(m_id):
                        res = power.set_powered(m_id, True)
                        if res.status == "ok":
                            shedded_machines.discard(m_id)
                            print(f"[POWER GUARD] Restored {m_id} — solar surplus available ({generated_w:.0f} W gen vs {consumed_w:.0f} W con).")
                except Exception:
                    pass

    # 6. Daily hardware advisory warnings (printed once per day at sunset/night)
    if is_night and current_day != last_advisory_day:
        last_advisory_day = current_day

        # Check battery capacity vs baseline night load (~25W * night_duration)
        baseline_wh = max(consumed_w, 25.0) * night_duration
        if capacity_wh < baseline_wh:
            shortfall = baseline_wh - capacity_wh
            bats_needed = int(shortfall // 500) + 1
            print(f"[POWER ADVISORY] Battery capacity ({capacity_wh:.0f} Wh) is insufficient to run baseline loads through the night ({baseline_wh:.0f} Wh needed). Recommend buying {bats_needed}x Battery (300 cr each) at the Shop.")

        # Check if generation reached full charge today
        if capacity_wh > 0 and peak_day_battery_wh < (capacity_wh * 0.90):
            charge_pct = (peak_day_battery_wh / capacity_wh) * 100
            print(f"[POWER ADVISORY] Solar generation deficit! Batteries only reached {charge_pct:.0f}% charge during the day. Recommend buying at least 1x Solar Generator (500 cr) at the Shop.")

    sleep(1.0)

