                location = f"({getattr(vehicle, 'x', 0):.0f}, {getattr(vehicle, 'y', 0):.0f})"
            panel.draw_text(width * 0.78, y + 14, location, 11, "text-secondary")

            rescue = getattr(vehicle, "rescue_status", "none")
            if rescue != "none":
